import ipaddress

def correspond(regle, ip, port):
    action, source, port_regle = regle
    dans = ipaddress.ip_address(ip) in ipaddress.ip_network(source)
    return dans and (port_regle == "*" or port_regle == port)

def rejouer(regles, connexions):
    decisions = []
    utilisees = set()
    for ip, port in connexions:
        action = "refuser"
        for i, regle in enumerate(regles):
            if correspond(regle, ip, port):
                action = regle[0]
                utilisees.add(i)
                break
        decisions.append(ip + ":" + str(port) + " -> " + action)
    inutiles = [i for i in range(len(regles)) if i not in utilisees]
    return {"décisions": decisions, "inutilisées": inutiles}
